style.css:
/* === CLAUDE MISSION TERMINAL THEME === */

* {
  font-family: 'Fira Code', 'Cascadia Code', 'Consolas', 'Menlo', monospace !important;
  border-radius: 0px !important;
  box-shadow: none !important;
}

/* Pitch black background and glowing green text */
body, main, header, nav, aside, div, section {
  background-color: #030803 !important;
  color: #00ff41 !important;
  border-color: #004d14 !important;
}

/* Force all text, headings, and lists to terminal green */
p, span, h1, h2, h3, li, code, pre, textarea {
  color: #00ff41 !important;
  text-shadow: 0 0 4px rgba(0, 255, 65, 0.4) !important;
}

/* Style the chat input box like a raw command line */
fieldset, [contenteditable="true"] {
  background-color: #050f05 !important;
  border: 1px solid #00ff41 !important;
}

[contenteditable="true"]::before {
  content: "> ";
  color: #00ff41;
  font-weight: bold;
}

/* Tint icons and images green */
svg, img {
  filter: sepia(100%) hue-rotate(85deg) saturate(500%) brightness(0.9) !important;
}

/* Subtle CRT monitor scanlines across the screen */
body::after {
  content: " ";
  display: block;
  position: fixed;
  top: 0; left: 0; bottom: 0; right: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.35) 50%);
  background-size: 100% 3px;
  z-index: 999999;
  pointer-events: none;
}
